from collections import Counter

# Get all shapes properly formatted
all_shapes = []
for info in cluster_info:
    r0, c0 = info['bbox'][0], info['bbox'][1]
    h, w = info['height'], info['width']
    subgrid = [[grid[r0+r][c0+c] for c in range(w)] for r in range(h)]
    # Convert everything to tuples recursively
    def to_tuple(obj):
        if isinstance(obj, list):
            return tuple(to_tuple(x) for x in obj)
        return obj
    shape = to_tuple(subgrid)
    all_shapes.append((info['id'], shape))

# Count unique shapes
shape_counts = Counter([shape[1] for shape in all_shapes])
print("Unique shapes found:")
for shape_val, count in sorted(shape_counts.items(), key=lambda x: -x[1]):
    print(f"\nShape ({count} occurrences):")
    if isinstance(shape_val, int):
        print(f"  Single pixel: 8")
    else:
        for row in shape_val:
            print(" " + " ".join(str(x) for x in row))

# Show positions for each shape
print("\n\nPositions by shape type:")
shape_to_positions = {}
for pos, shape in all_shapes:
    shape_key = str(shape)
    if shape_key not in shape_to_positions:
        shape_to_positions[shape_key] = []
    shape_to_positions[shape_key].append(pos)

for shape_key, positions in list(shape_to_positions.items())[:10]:
    # Show first occurrence's bbox
    occ = cluster_info[positions[0]]
    print(f"{shape_key[:50]}...: {occ['bbox']} -> count={len(positions)}")

